# ---------- ModelNew class using the custom kernels ----------
class ModelNew(nn.Module):
    def __init__(self, in_channels: int = 64, out_channels: int = 128, kernel_size: int = 3,
                 stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Build a weight tensor of shape (out_channels, in_channels, kernel_size, kernel_size)
        weight = torch.ones(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size, dtype=torch.float)
        return conv2d_cuda(x, weight, self.in_channels,
                            self.out_channels,
                            self.kernel_size, self.kernel_size,
                            self.stride, self.padding, self.dilation)
